DROP TABLE IF EXISTS `producto_vendedors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `producto_vendedors` (
  `producto_id` bigint unsigned NOT NULL,
  `almacen_id` bigint unsigned NOT NULL,
  `precio_venta` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Precio asignado por el vendedor',
  `venta_ganancia` decimal(10,2) NOT NULL DEFAULT '0.00',
  `comision` decimal(8,2) NOT NULL DEFAULT '0.00',
  `precio_admin` decimal(10,2) DEFAULT NULL COMMENT 'Precio base establecido por el administrador',
  `ganancia_admin` decimal(10,2) DEFAULT NULL COMMENT 'Ganancia base calculada del precio admin',
  `puesto_por_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`producto_id`,`almacen_id`),
  KEY `producto_vendedors_puesto_por_user_id_foreign` (`puesto_por_user_id`),
  KEY `producto_vendedors_almacen_id_precio_venta_index` (`almacen_id`,`precio_venta`),
  CONSTRAINT `producto_vendedors_almacen_id_foreign` FOREIGN KEY (`almacen_id`) REFERENCES `almacens` (`id`) ON DELETE CASCADE,
  CONSTRAINT `producto_vendedors_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `producto_vendedors_puesto_por_user_id_foreign` FOREIGN KEY (`puesto_por_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

