DROP TABLE IF EXISTS `productos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `productos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nombre_producto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion_producto` text COLLATE utf8mb4_unicode_ci,
  `marca_producto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modelo_producto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `capacidad_producto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_producto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `codigo_producto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barcode_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categoria_id` bigint unsigned NOT NULL,
  `precio_compra_producto` decimal(10,2) NOT NULL DEFAULT '0.00',
  `precio_venta_actualizado` decimal(10,2) NOT NULL DEFAULT '0.00',
  `cantidad_producto` int NOT NULL DEFAULT '0',
  `imagen_producto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'productos/producto-default.png',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `productos_codigo_producto_unique` (`codigo_producto`),
  KEY `productos_categoria_id_foreign` (`categoria_id`),
  KEY `productos_codigo_producto_index` (`codigo_producto`),
  CONSTRAINT `productos_categoria_id_foreign` FOREIGN KEY (`categoria_id`) REFERENCES `categorias` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=539 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
